window.REVIEWS=[{"id":"249580103","name":"Константин !","date":"2026-06-12","text":"Улахан махтал Дмитрийга Алексейга✊🏼ессе да сайда турун! всем советую👍🏼","answer":true,"imgs":["img/rv/249580103.jpg"]},{"id":"248641972","name":"Виктория Пинигина","date":"2026-06-09","text":"Огромное спасибо команде Dragon Motors за авто из Китая! 🙏🏼🔥 Отдельные слова благодарности — Алексею 🤗 Таких компаний по городу достаточно, но с первого же диалога у меня появилось доверие и уверенность, что я буду заказывать именно у них. Алексей быстро отвечал, сразу нашел подходящую машину — в которую я влюбилась с первого взгляда 😍","answer":true,"imgs":["img/rv/248641972.jpg"]},{"id":"246617106","name":"Михаил Я","date":"2026-06-01","text":"Брал машину у них, всем доволен, по срокам все как обещали, постоянная обратная связь и помощь в с различными вопросами 👍🏻 рекомендую покупать через них, не прогадаете ✊🏻","answer":true,"imgs":["img/rv/246617106.jpg"]},{"id":"242813398","name":"City spirit","date":"2026-05-16","text":"Лучшие в своем деле✊🏻 рекомендую 👍🏻заказывал для себя, благодарю Дмитрия, полное сопровождение сделки от начала консультации до вручения автомобиля","answer":true,"imgs":["img/rv/242813398.jpg","img/rv/242813398-1.jpg"]},{"id":"239449047","name":"анатолий григорьев","date":"2026-04-30","text":"Дима5а уонна Алексейга кеме5ут иьин улахан махтал! Ба5алаах массыынабын в срок булан талан а5алан аукционна сууйэн биэрдилэр. Субэлиибин!","answer":true,"imgs":["img/rv/239449047.jpg"]},{"id":"237009553","name":"Михаил Корнилов","date":"2026-04-19","text":"Огромное спасибо Алексею и Дмитрию за качественную работу. Обратились 17 марта за консультацией, на завтра выиграли аукцион. Машина 08.04 прибыла во Владивосток, 10.04 растаможена. В Якутск прибыл уже 14.04. Итого и месяца не прошло с момента консультации. Ребята работают четко, прозрачно, на все вопросы дают полный ответ. Рекомендую!","answer":true,"imgs":["img/rv/237009553.jpg"]},{"id":"215801400","name":"Алексей Петухов","date":"2026-01-31","text":"Благодарю компанию за исполнение моих пожеланий,работают на качество и совесть,все прозрачно никаких скрытых комиссий. приобрел сузуки джимни","answer":true,"imgs":["img/rv/215801400.jpg","img/rv/215801400-1.jpg"]},{"id":"215350623","name":"Борис Борисов","date":"2026-01-29","text":"Ребятам большой респект, профессионалы своего дела, расскажут, покажут, объяснят! Смело заказывайте авто у них, дорожат своей репутацией! Я не в первый раз заказываю авто через аукцион, поэтому есть с чем сравнивать. Задача лишь бы купить не ставилась, лот выиграть не могли недели три. Клиент я дотошный, можно сказать чуточку вредный, но везение и удача сошлись в тот день, Степвагон выиграли по низу рынка, примерно на 400тр. Выиграли на строгом хондовском аукционе, 3,5 балла. Если честно, то царапин вообще не нашел. Мне кажется после выигрыша машина дольше доставлялись до места погрузки в Японии, так как после прибытия расстаможилась в течении пары дней. Машиной доволен, купил, то, что хотел. Ребятам процветания и больше довольных клиентов.","answer":true,"imgs":["img/rv/215350623.jpg","img/rv/215350623-1.jpg"]},{"id":"214587224","name":"Irina Soloveva","date":"2026-01-26","text":"Выражаю огромную благодарность компании Dragon Motors за грамотную систему работы и помощь в покупке машины мечты! Желаю дальнейшего процветания!","answer":true,"imgs":["img/rv/214587224.jpg"]},{"id":"214207059","name":"Степан Сергеев","date":"2026-01-24","text":"Ребятам спасибо за доставку хорошего автомобиля быстро и раньше срока. Желаю процветания и удачи вам! 🙌🏽✊🏽","answer":true,"imgs":["img/rv/214207059.jpg"]},{"id":"210115334","name":"Антонина Протасова","date":"2026-01-04","text":"Хотим выразить огромную благодарность ребятам из Драгон моторс , помогли выбрать, купить, привезти, машину с хорошей аукционной оценкой, учитывая бюджет . Весь процесс был прозрачный , без скрытых комиссий и всегда на связи на всех стадиях , начиная от подбора заканчивая получением машины. Однозначно рекомендую🤲🏻","answer":true,"imgs":["img/rv/210115334.jpg"]},{"id":"207628111","name":"Арсен Андреев","date":"2025-12-24","text":"Улахан махтал, 2 неделя иьигэр массыына кэллэ, оьуобай эбит, тымныыга томмот👍 Сыаналара удамыр, улэлэрин сатыыр уолаттар👍","answer":true,"imgs":["img/rv/207628111.jpg"]},{"id":"203746544","name":"Михаил Готовцев","date":"2025-12-03","text":"Огромное спасибо Дмитрию! Получил машину в указанный срок ещё чуть пораньше, можно сказать с помощью фирмы Драгон Моторс запрыгнули в последний поезд перед утильсбором! Ещё раз огромное спасибо ребятам! Я уже 3 машину заказываю всегда без проблем в указанный срок, ребята всегда на связи!!!","answer":true,"imgs":["img/rv/203746544.jpg"]},{"id":"202828040","name":"Елена Тимофеева","date":"2025-11-29","text":"Огромная благодарность Алексею и Дмитрию за вашу работу🙌🏻 машину сегодня получила, очень довольна покупкой😍 два года назад через Дмитрия заказывала машину с Японии, в этот раз заказала с Китая. Ребята молодцы, профессионалы своего дела👍🏻 желаю развиваться дальше, много благодарных клиентов, буду рекомендовать вас🤗","answer":true,"imgs":["img/rv/202828040.jpg"]},{"id":"198668106","name":"Николай Федоров","date":"2025-11-10","text":"Хочу выразить огромную благодарность этой фирме за привоз санкционного автомобиля за очень короткие сроки и самое главное по цене ниже чем предлагали другие фирмы. Этих ребят нашел по сарафанному радио у знакомых которые также остались довольны покупкой авто через них. Перед заказом авто обошел почти все фирмы и частников которые занимаются привозом авто с аукционов, но выбрал эту фирму т.к не первый раз заказываю машины с аукционов Японии, и имею какой-то опыт покупки авто с аукциона, до этого заказывал через Владивостокские и наши местные фирмы. Здесь понравилось именно то что ребята работают прозрачно, без скрытых комиссий, поборов, налогов на каждом этапе, также понравилось, что ребята имеют огромный опыт, отлично разбираются в аукционных листах, комплектациях в автомобилей, советуют с каких аукционов стоит покупать авто, с каких лучше воздержаться. Всем рекомендую данную фирму, сэкономите деньги и нервы работая с профессионалами своего дела!","answer":true,"imgs":["img/rv/198668106.jpg"]},{"id":"198517950","name":"Василий Бурцев","date":"2025-11-09","text":"Улахан Махтал Дмитрийга, туох да проблемата суох Япониятан 🚙 ылан киллэрдилэр👍 массыына олох чуоккай. Бу уолаттары рекомендую проссец барыта прозрачнай туох да эбии телееьун суох. Сакаастаан👍👍👍","answer":true,"imgs":["img/rv/198517950.jpg","img/rv/198517950-1.jpg"]},{"id":"193793195","name":"Арсений Аммосов","date":"2025-10-18","text":"Спасибо большое Дмитрию и Алексею, первый раз взял машину без пробега по РФ, очень хорошо подобрали, весь процесс покупки без всяких проблем, остался очень доволен. Рекомендую данную компанию, цены действительно очень выгодные.","answer":true,"imgs":["img/rv/193793195.jpg"]},{"id":"192045068","name":"Alya .","date":"2025-10-11","text":"«Драгон моторска» улахан махтал! Август ыйга сана АКПП заказтаабытым, ыйынан уже туппутум. Сыаната дилертан икки тогул чэпчэки буолан тазыста👍","answer":true,"imgs":["img/rv/192045068.jpg"]},{"id":"189514627","name":"Tanya Chemezova","date":"2025-09-29","text":"Массыынабытын туттубут😍🤩Олох огонь🔥👍🏻👍🏻👍🏻Маладьыастар на совесть улэлиир эбиккит👍🏻👏🏻👏🏻👏🏻Оссо да улэ5ит таьаарыылаах буоллун🙌🏻Тус олоххутугар дьолу,кытаанах доруобуйаны✊🏼","answer":true,"imgs":["img/rv/189514627.jpg"]},{"id":"188149074","name":"Милена Косметолог","date":"2025-09-23","text":"Спасибо за помощь и покупку машины, рав 4,2025. Все быстро, четко. На каждом этапе помощь. Все вопросы, всегда на связи. Алексей, лучший.","answer":true,"imgs":["img/rv/188149074.jpg"]},{"id":"184790672","name":"Canter 862","date":"2025-09-06","text":"Спасибо Дмитрию ! Все четко по факту ,без скрытых комиссий , очень довольны. Доставили автомобиль до г.Владивосток в сроки . Всем рекомендую 👍","answer":true,"imgs":["img/rv/184790672.jpg"]},{"id":"184748214","name":"Юрий Лазарев","date":"2025-09-06","text":"Спасибо Дмитрию, уже несколько раз брал машины с Японии для себя👍🏻 Всегда всё быстро и четко. В этом году учли все мои пожелания и доставили машину в отличном состоянии в кратчайшие сроки✊🏻 Желаю много клиентов, заказов.","answer":true,"imgs":["img/rv/184748214.jpg","img/rv/184748214-1.jpg","img/rv/184748214-2.jpg"]},{"id":"184681728","name":"arrow","date":"2025-09-06","text":"Спасибо Алексею за помощь в приобретение и подборе! Всем довольны!","answer":true,"imgs":["img/rv/184681728.jpg"]},{"id":"184678826","name":"Arcticwhite","date":"2025-09-06","text":"Спасибо Алексею за предоставленную возможность купить автомобиль из Китая. Всё прошло точно так, как описал Алексей. Автомобилем доволен, купили именно такую какую хотели приобрести.","answer":true,"imgs":["img/rv/184678826.jpg"]},{"id":"184675236","name":"Сандал Попов","date":"2025-09-06","text":"Спасибо Алексею за отличную возможность приобрести мою первую автомашину из Китая, именно тот, который я рассматривал и мечтал в течении года. Алексей держал меня в курсе всего, и на каждом шагу покупки автомобиля все четко разъяснял. Покупкой очень доволен, кайф 👍","answer":true,"imgs":["img/rv/184675236.jpg","img/rv/184675236-1.jpg","img/rv/184675236-2.jpg"]},{"id":"184547453","name":"Тимофей Колмогоров","date":"2025-09-05","text":"Заказывали у Димы машину из Японии. Проделав много работы, нашли именно ту самую машину, которую так долго искали! Очень много подсказывал, рассказывал нюансы, о которых мы не знали. Отзывчивый, быстро отвечает, подбирает реально стоящие варианты. Еще раз спасибо!!","answer":true,"imgs":["img/rv/184547453.jpg"]},{"id":"184534551","name":"🥋 🔥","date":"2025-09-05","text":"Купил свой автомобиль через Дмитрия, о чем ни разу не пожалел. Подберет, выиграет, доставит именно ту машину, которую Вы искали👍🏻","answer":true,"imgs":["img/rv/184534551.jpg"]},{"id":"184523680","name":"Vitaliy Potapov","date":"2025-09-05","text":"Дмитрия знаю довольно давно, поэтому решил обратиться сразу к нему.В декабре 2024 года заказал автомобиль SUBARU LEVORG, несмотря на новогодние каникулы автомобиль пришел довольно быстро. Из всех представленных вариантов, выбрали один и не прогадали. Тачка огонь, именно то, что хотел 👍🏻 В июле 2025 года решил, также обратиться к Дмитрию для покупки второго авто SUZUKI JIMNY. И снова попадание 10 из 10 🔥 Очень доволен клиентоориентированностью Дмитрия и его подходом к работе. По смете Дмитрий сразу же сообщает, когда какие транши нужно будет оплатить - это очень большой плюс. Также сообщает о сроках, таможню и лабораторию проходят быстро 🏎️ , ниразу не было простоев. Желаю компании Драгон Моторс процветания и побольше клиентов.🤝🏼🙌🏼","answer":true,"imgs":["img/rv/184523680.jpg","img/rv/184523680-1.jpg","img/rv/184523680-2.jpg"]},{"id":"184522515","name":"Николай Софронеев","date":"2025-09-05","text":"🤝Заказал авто с японии у Дмитрия рекомендую все быстро и четко проделанной работой доволен на мои вопросы тут же отвечает на всех этапах доставки авто профессионал своего дела 👍🏻","answer":true,"imgs":["img/rv/184522515.jpg"]},{"id":"184518923","name":"Viktor Bobkov","date":"2025-09-05","text":"Всё отлично, спасибо Диме что уговорил заказать хонда Фрид 2012 года, а не 2010г , оно того стоит. Большой, вместительный.","answer":true,"imgs":["img/rv/184518923.jpg"]},{"id":"184517284","name":"Свободный Кочевник","date":"2025-09-05","text":"Не первый год заказываю машину через Диму, Honda Fit Shuttle, Toyota Isis, и вот последний Suzuki Swift работает профессионально, машины в срок пришли.","answer":true,"imgs":["img/rv/184517284.jpg","img/rv/184517284-1.jpg"]},{"id":"184517146","name":"Никита Петрович","date":"2025-09-05","text":"Обращались для провоза авто из Японии, Понравилась работа Дмитрия Владиславовича Доставили очень быстро, о каждом этапе информировали, авто под ключ, сделка прошла максимально прозрачно, остались довольны, будем обращаться ещё и другим советовать 👍 Успехов в работе и процветания!","answer":true,"imgs":["img/rv/184517146.jpg"]},{"id":"303594739","name":"Никита П","date":"2026-10-07","text":"Весной 2026 г.воспользовался услугами Драгон Моторс.Ребята-Профи👍👍👍 Объяснили цепочку,сопровождали весь период от А до Я,нашли отличную машину по нашим желаниям и по размеру бюджета. Система налажена у ребят,все четко объясняют.Можете спокойно обратиться если вы в поиске машины через аукцион. Дмитрию и Алексею успехов в работе и много благодарных клиентов как я✊🏻✊🏻✊🏻","answer":false,"imgs":[]},{"id":"297435218","name":"Александр Оконешников","date":"2026-09-17","text":"Большое спасибо Диме🤝 заказал и доставил автовозом👍 рекомендую","answer":false,"imgs":[]},{"id":"265993904","name":"Нюргустан Силин","date":"2026-08-07","text":"Отличная компания в такой сложной ситуации с топливом обеспечил доставку автовозом и вообще всё отлично буду рекомендовать Дмитрия своим друзьям","answer":true,"imgs":[]},{"id":"248527865","name":"KANA","date":"2026-06-08","text":"Спасибо Дмитрию за высокую клиентоориентированность,от начало до конца контролировал весь процесс доставки авто до Якутска,процветания и больше довольных клиентов🙌","answer":true,"imgs":[]},{"id":"244567992","name":"pobeda step...","date":"2026-05-24","text":"махталларын🙌олус түргэнник массыынабын ылан азалан биэрбиккитигэр🙌үүнэ сайда турун✊✊✊","answer":true,"imgs":[]},{"id":"242187831","name":"Игорь Владимиров","date":"2026-05-13","text":"Спасибо большое Алексею за подбор, доставку и помощь в покупке нашего авто с Китая 👍👍👍👏👏👏Все сделал оперативно, качественно, прозрачно и на совесть. Были и варианты других авто, но после доп проверки, выяснилось, что пробег у них скрученный. Поэтому, Алексей попросил немного подождать и выбрать наиболее хороший вариант. И уже через 2 дня, этот вариант нашелся👍👍👍Машину пригнали сами с супругой, по авто всё устраивает. В Драгон моторс работают настоящие профессионалы своего дела, подходят к делу ответственно и качественно. Еще раз большое спасибо!!!✊✊✊","answer":false,"imgs":[]},{"id":"241153725","name":"Николай Посельский","date":"2026-05-08","text":"Драгон моторска Димаҕа барҕа махтал быраат Алеша массыынатын заказтаан этэҥҥэ кэлэн билигин үөрүүтэ муҥура суох. Бүгүн нүөмэр ылла .Драгон моторс уолаттарга үлэҕит ситиһиилээх тахсыылаах сатабыллаах буоллун Сахам дьонугар саха уолаттарыгар массыыната заказтаан эрэллээх уолаттар 👍👍👍✊✊✊","answer":false,"imgs":[]},{"id":"241038285","name":"Михаил Арзамазов","date":"2026-05-07","text":"Заказываю уже второй раз машину молодцы, подбирают машину по моим параметрам цены даже меньше чем я ращитывал. Доставка быстрая. Процветания. ✊✊✊","answer":true,"imgs":[]},{"id":"229266869","name":"Геннадий Васильев","date":"2026-03-15","text":"Спасибо DRAGON MOTORS за оперативную доставку автомобилей прямо с Японии. Индивидуальный подход к каждому клиенту, учитывают каждое желание клиента, его хотелку. Предоставляют большой выбор автомобилей, в соответствии с финансовыми возможностями клиента. Я заказывал 2 автомобиля, оба заказа доставили прямо до г. Якутска, в срок, в целости и сохранности.","answer":true,"imgs":[]},{"id":"203933708","name":"Николай Яковлев","date":"2025-12-04","text":"Когда продали машину начались поиски фирмы которая привезла бы в короткие сроки авто перед вступлением в силу утильсбора. Обращался в несколько фирм, в том числе Владивостокские. Эту фирму случайно нашел в 2гис. Несмотря на выходные ответили и скинули ориентировочные цены. После когда уже конкретно искал, цена на одну и ту же машину у них была на порядок ниже. Привезли машину в указанные сроки, даже чуть пораньше. Не хватает маленько сервиса, типа встретить в аэропорту итп итд) но зато все честно и на порядок дешевле. Машину забрал так просто обыденно, как будто сходил в магазин за хлебом))рекомендую!","answer":true,"imgs":[]},{"id":"203151569","name":"Игорь Макаров","date":"2025-12-01","text":"Большое спасибо Dragon Motors, сегодня получили машину, всегда на связи, отвечают на все вопросы, рекомендую 👍","answer":true,"imgs":[]},{"id":"195812505","name":"Николай Петухов","date":"2025-10-28","text":"Огромное спасибо! Работают отлично, всегда на связи👍 Рекомендую","answer":true,"imgs":[]},{"id":"192427165","name":"Иван Максимов","date":"2025-10-13","text":"Саха «Драгон моторс» хампаанньа5а биһиги дьиэ кэргэн номнуо хаһыс да массыынабытын сакаастаатыбыт. Үлэтэ олох чуоккай, түргэн-тарҕан, биир тылынан профессионально үлэлиир. Массыынаны сатаан быһаарсыбат да киһи кинилэргэ эрэнэн сакаастаан баран сылдьар. Бэйэлэрэ барытын көрөн-истэн, дьаһайан түргэн кэмҥэ массыынаҕын тутаҕын👍👍 Саҥа кэми кытта тэҥҥэ хардыылыыр тэрилтэҕэ үлэҕитигэр инникитин сайдыыны, элбэх махталлаах клиеннары баҕарабыт.","answer":true,"imgs":[]},{"id":"187555443","name":"Евгений Я.","date":"2025-09-20","text":"Димаҕа улахан махтал! Ийэбэр китайтан массыына заказтаапыппыт Хонда Везель 2021 сыллаах. 1 ыйынан массыынабытын ылбыппыт. Барытын учугэйдик быһаарар, консультациялыыр. Рекомендую👍","answer":true,"imgs":[]},{"id":"186747936","name":"Alexey Nesterov","date":"2025-09-16","text":"Дмитрию большое спасибо. Работают четко, всю информацию сразу сообщают, на вопросы отвечают детально. В этом году заказал вторую машину, уже в пути. Рекомендую","answer":true,"imgs":[]},{"id":"185975110","name":"Николай Александров","date":"2025-09-12","text":"Недавно продали машину и искали чтото семейное, рекомендовали Драгон Моторс. Оказывается удобно брать машину «со стоянки из японии», купили виш👍🏻состояние отл","answer":true,"imgs":[]},{"id":"184584277","name":"Apple User","date":"2025-09-05","text":"В прошлом году заказывала Тойоту витц через Дмитрия. Выбрала на месте во время консультации 3 варианта из представленных на аукционе и на завтрашний день по нашей ставке один из них был выигран. Как итог, машина была уже у меня через 1,5 месяца. Прошел год с момента получения авто и ни разу не пожалела о своем выборе. На техосмотре похвалили и сказали, что машина просто высший класс)) Спасибо, что привезли в целости и сохранности","answer":true,"imgs":[]},{"id":"184513354","name":"Николай Панкратов","date":"2025-09-05","text":"Если в выборе машины с аукционов Японии, то всем рекомендую Дмитрия, приобретал в 2022 Ноах, в 2024 Витц, все отлично, ни каких скрытых комиссий, полностью сопроводил сделку, очень ответственный и дисциплинированный, дальше также буду заказывать у Дмитрия","answer":true,"imgs":[]}];
